window.ATLAS_GLOSSARY=[{"id":"network","term":"Network","definition":"Two or more devices connected so they can share information or services.","example":"Your phone and laptop using the same home Wi-Fi are on a network.","category":"Digital basics","level":"foundation","detail":"The internet is only one network of networks. Your home LAN can keep exchanging files even when your internet subscription is disconnected.","common_mistake":"Network is not another word for internet."},{"id":"node","term":"Node","definition":"Any device or point that participates in a network.","example":"A printer, laptop, or router can be a node.","category":"Digital basics","level":"foundation"},{"id":"host","term":"Host","definition":"A device that sends or receives data, usually with an IP address.","example":"Your computer is a host when it visits a website.","category":"Digital basics","level":"foundation"},{"id":"client","term":"Client","definition":"A device or program that requests a service.","example":"A browser acts as a client when it asks a web server for a page.","category":"Digital basics","level":"foundation"},{"id":"server","term":"Server","definition":"A device or program that provides a service to clients.","example":"A DNS server answers questions about website names.","category":"Digital basics","level":"foundation"},{"id":"peer-to-peer","term":"Peer-to-peer","definition":"Devices sharing directly without always relying on a central server.","example":"Two computers can exchange files directly on a small network.","category":"Digital basics","level":"foundation"},{"id":"lan","term":"LAN","definition":"Local area network: devices connected within a home, office, or building.","example":"The computers in your showroom might share a LAN.","category":"Digital basics","level":"foundation"},{"id":"wan","term":"WAN","definition":"Wide area network: a connection linking networks over long distances.","example":"An internet provider connects many local networks across a WAN.","category":"Digital basics","level":"foundation"},{"id":"internet","term":"Internet","definition":"The worldwide collection of connected networks that use Internet Protocol.","example":"A home router connects your local network to the internet.","category":"Digital basics","level":"foundation"},{"id":"intranet","term":"Intranet","definition":"A private network or website intended for members of an organization.","example":"An employee-only company portal can be an intranet.","category":"Digital basics","level":"foundation"},{"id":"protocol","term":"Protocol","definition":"An agreed set of rules devices follow when communicating.","example":"TCP and IP are two protocols with different jobs.","category":"Digital basics","level":"foundation"},{"id":"standard","term":"Standard","definition":"A published specification designed to let systems work together.","example":"Ethernet is based on IEEE standards.","category":"Digital basics","level":"foundation"},{"id":"rfc","term":"RFC","definition":"Request for Comments: a numbered publication, often defining internet protocols.","example":"RFC 1918 describes private IPv4 address ranges.","category":"Digital basics","level":"foundation"},{"id":"bit","term":"Bit","definition":"A single binary value, 0 or 1.","example":"Eight bits can represent one byte.","category":"Digital basics","level":"foundation"},{"id":"byte","term":"Byte","definition":"A group of eight bits.","example":"A file of 1,000 bytes contains 8,000 bits.","category":"Digital basics","level":"foundation"},{"id":"binary","term":"Binary","definition":"A number system using only zeros and ones.","example":"Binary 1010 equals decimal 10.","category":"Digital basics","level":"foundation"},{"id":"hexadecimal","term":"Hexadecimal","definition":"A base-16 numbering system using 0–9 and A–F.","example":"MAC addresses are commonly written in hexadecimal.","category":"Digital basics","level":"foundation"},{"id":"bandwidth","term":"Bandwidth","definition":"The maximum amount of data a link can carry per second.","example":"A 1 Gbps port has higher capacity than a 100 Mbps port.","category":"Digital basics","level":"foundation"},{"id":"throughput","term":"Throughput","definition":"The actual data rate achieved in real conditions.","example":"A 1 Gbps link might deliver less than 1 Gbps of usable traffic.","category":"Digital basics","level":"foundation"},{"id":"goodput","term":"Goodput","definition":"Useful application data delivered per second, excluding overhead.","example":"File-transfer goodput is lower than the raw link rate.","category":"Digital basics","level":"foundation"},{"id":"latency","term":"Latency","definition":"Time it takes data to travel from one point to another.","example":"A video call feels delayed when latency is high.","category":"Digital basics","level":"foundation"},{"id":"jitter","term":"Jitter","definition":"How much a packet's delay varies over time.","example":"Uneven delay can make a voice call sound choppy.","category":"Digital basics","level":"foundation"},{"id":"packet-loss","term":"Packet loss","definition":"Packets that never reach their intended destination.","example":"Congestion may cause a video call to drop frames.","category":"Digital basics","level":"foundation"},{"id":"duplex","term":"Duplex","definition":"Whether communication can happen in one direction or both at once.","example":"Modern switched Ethernet normally uses full duplex.","category":"Digital basics","level":"foundation"},{"id":"full-duplex","term":"Full duplex","definition":"Sending and receiving at the same time.","example":"A computer can upload and download over one Ethernet link.","category":"Digital basics","level":"foundation"},{"id":"half-duplex","term":"Half duplex","definition":"Taking turns sending and receiving.","example":"Old shared Ethernet media worked this way.","category":"Digital basics","level":"foundation"},{"id":"topology","term":"Topology","definition":"The layout of network devices and connections.","example":"A star topology connects devices to a central switch.","category":"Digital basics","level":"foundation"},{"id":"physical-topology","term":"Physical topology","definition":"The actual cable and equipment layout.","example":"A switch has one cable to each desk.","category":"Digital basics","level":"foundation"},{"id":"logical-topology","term":"Logical topology","definition":"How traffic or network relationships are organized, independent of cabling.","example":"Two VLANs can share a physical switch but remain logically separate.","category":"Digital basics","level":"foundation"},{"id":"nic","term":"NIC","definition":"Network interface card: hardware that connects a device to a network.","example":"Your laptop's Ethernet port belongs to a NIC.","category":"Devices and physical connections","level":"foundation"},{"id":"switch","term":"Switch","definition":"A device that usually forwards Ethernet frames using MAC addresses.","example":"A switch delivers a frame toward the right PC port.","category":"Devices and physical connections","level":"foundation","detail":"Think of a switch as an intelligent mail sorter inside one local neighborhood. It observes the source MAC of incoming frames and remembers which port leads to that device. When the destination is already known, it forwards to the correct port; if unknown, it floods to eligible ports in that VLAN.","common_mistake":"A switch does not normally choose routes between unrelated IP networks."},{"id":"router","term":"Router","definition":"A device that forwards packets between IP networks.","example":"Your router moves traffic from home to your internet provider.","category":"Devices and physical connections","level":"foundation","detail":"A router joins different IP networks. It examines the packet's destination IP address, consults its routing table, chooses a next hop, and builds the correct new link-layer frame for the outgoing interface.","common_mistake":"Routers forward by destination IP prefix; they do not carry the original Ethernet MAC addresses unchanged across every hop."},{"id":"firewall","term":"Firewall","definition":"A system that allows or blocks traffic according to security rules.","example":"A firewall can deny unsolicited connections from the internet.","category":"Devices and physical connections","level":"foundation","detail":"A firewall enforces policy between trust zones or endpoints. A stateful firewall tracks connections so replies to allowed sessions can be evaluated in context, unlike a simple stateless packet filter.","common_mistake":"Firewalls are not automatically perfect protection, and security still requires patching and access control."},{"id":"access-point","term":"Access point","definition":"A device that bridges wireless clients into a network.","example":"An office access point gives phones Wi-Fi access.","category":"Devices and physical connections","level":"foundation"},{"id":"modem","term":"Modem","definition":"Equipment that converts between a provider's access technology and network data.","example":"A cable modem connects a home to cable internet service.","category":"Devices and physical connections","level":"foundation"},{"id":"gateway","term":"Gateway","definition":"A system that connects or translates between networks or protocols.","example":"A default gateway is where a PC sends off-network traffic.","category":"Devices and physical connections","level":"foundation"},{"id":"hub","term":"Hub","definition":"An older Layer 1 device that repeats incoming signals to every port.","example":"A hub doesn't learn MAC addresses like a switch.","category":"Devices and physical connections","level":"foundation"},{"id":"repeater","term":"Repeater","definition":"A device that regenerates a signal to extend its usable reach.","example":"A wired repeater can extend a link under suitable conditions.","category":"Devices and physical connections","level":"foundation"},{"id":"bridge","term":"Bridge","definition":"A Layer 2 device joining network segments.","example":"A wireless bridge can connect two buildings.","category":"Devices and physical connections","level":"foundation"},{"id":"transceiver","term":"Transceiver","definition":"A module that sends and receives electrical or optical signals.","example":"An SFP module connects a switch to fiber.","category":"Devices and physical connections","level":"foundation"},{"id":"sfp","term":"SFP","definition":"Small form-factor pluggable: a replaceable interface module.","example":"Insert an approved fiber SFP into a switch port.","category":"Devices and physical connections","level":"foundation"},{"id":"qsfp","term":"QSFP","definition":"Quad small form-factor pluggable: a high-speed transceiver family.","example":"Data-center switches use QSFP modules for fast uplinks.","category":"Devices and physical connections","level":"foundation"},{"id":"copper-cable","term":"Copper cable","definition":"Cable that carries electrical signals, commonly twisted-pair Ethernet.","example":"Cat6 cable links a computer to a switch.","category":"Devices and physical connections","level":"foundation"},{"id":"twisted-pair","term":"Twisted pair","definition":"Wires twisted together to reduce interference.","example":"Cat5e Ethernet has four twisted pairs.","category":"Devices and physical connections","level":"foundation"},{"id":"cat5e","term":"Cat5e","definition":"A twisted-pair cabling category commonly used for 1 Gbps Ethernet.","example":"A short Cat5e run can support a Gigabit Ethernet connection.","category":"Devices and physical connections","level":"foundation"},{"id":"cat6","term":"Cat6","definition":"A cabling category with tighter electrical performance than Cat5e.","example":"A Cat6 cable can be used for many office switch connections.","category":"Devices and physical connections","level":"foundation"},{"id":"cat6a","term":"Cat6a","definition":"Cabling designed to support 10 Gigabit Ethernet over standard 100 m channel lengths.","example":"A modern office may choose Cat6a for long 10 Gbps runs.","category":"Devices and physical connections","level":"foundation"},{"id":"rj-45","term":"RJ-45","definition":"Common name for the eight-position modular Ethernet plug.","example":"You insert an Ethernet patch cable's plug into a switch.","category":"Devices and physical connections","level":"foundation"},{"id":"fiber-optic-cable","term":"Fiber optic cable","definition":"Cable that transmits light instead of electrical pulses.","example":"Fiber connects switches across long building runs.","category":"Devices and physical connections","level":"foundation"},{"id":"single-mode-fiber","term":"Single-mode fiber","definition":"Optical fiber with a small core suitable for long-distance links.","example":"A campus backbone may use single-mode fiber.","category":"Devices and physical connections","level":"foundation"},{"id":"multimode-fiber","term":"Multimode fiber","definition":"Optical fiber commonly used for shorter high-speed building links.","example":"Two nearby switches may connect with multimode optics.","category":"Devices and physical connections","level":"foundation"},{"id":"patch-panel","term":"Patch panel","definition":"A fixed termination board that organizes cable runs.","example":"Office wall-jack cables terminate in a rack patch panel.","category":"Devices and physical connections","level":"foundation"},{"id":"poe","term":"PoE","definition":"Power over Ethernet: delivering electrical power through network cabling.","example":"An access point can receive power from a PoE switch.","category":"Devices and physical connections","level":"foundation"},{"id":"pse","term":"PSE","definition":"Power sourcing equipment: a device that supplies PoE power.","example":"A PoE switch is often the PSE.","category":"Devices and physical connections","level":"foundation"},{"id":"pd","term":"PD","definition":"Powered device: a device receiving electrical power over Ethernet.","example":"An IP camera is a PD.","category":"Devices and physical connections","level":"foundation"},{"id":"emi","term":"EMI","definition":"Electromagnetic interference: unwanted electrical noise affecting signals.","example":"Running poorly shielded cable near motors can cause EMI.","category":"Devices and physical connections","level":"foundation"},{"id":"crc","term":"CRC","definition":"Cyclic redundancy check: a computed value used to detect errors in received frames.","example":"CRC errors may suggest cable or interface trouble.","category":"Devices and physical connections","level":"foundation"},{"id":"auto-negotiation","term":"Auto-negotiation","definition":"A procedure that agrees on link speed and duplex capabilities.","example":"A switch and computer may negotiate 1 Gbps full duplex.","category":"Devices and physical connections","level":"foundation"},{"id":"interface","term":"Interface","definition":"A network connection point, physical or virtual.","example":"GigabitEthernet0/1 is an interface name on some Cisco devices.","category":"Devices and physical connections","level":"foundation"},{"id":"mtu","term":"MTU","definition":"Maximum transmission unit: largest packet payload a link can carry without fragmentation at that layer.","example":"Ethernet commonly carries an IP MTU of 1500 bytes.","category":"Devices and physical connections","level":"foundation"},{"id":"osi-model","term":"OSI model","definition":"A seven-layer reference framework for describing network communication.","example":"Switch forwarding is commonly discussed at OSI Layer 2.","category":"Layers, frames, and transport","level":"foundation","detail":"Think of the layers as responsibilities rather than seven independent physical boxes. Layer 1 moves bits, Layer 2 handles local frames, Layer 3 routes packets, Layer 4 manages end-to-end transport, and the upper layers concern sessions and applications.","common_mistake":"The OSI model is a reference model; real protocols are organized more naturally around the TCP/IP stack."},{"id":"tcp-ip-model","term":"TCP/IP model","definition":"A practical layered model for internet protocols.","example":"IP belongs to the internet layer and TCP to transport.","category":"Layers, frames, and transport","level":"foundation"},{"id":"layer-1","term":"Layer 1","definition":"OSI physical layer: sends bits as electrical, optical, or radio signals.","example":"A broken Ethernet cable is a Layer 1 issue.","category":"Layers, frames, and transport","level":"foundation"},{"id":"layer-2","term":"Layer 2","definition":"OSI data-link layer: handles local frames and MAC addressing.","example":"VLANs and Ethernet switching are Layer 2 technologies.","category":"Layers, frames, and transport","level":"foundation"},{"id":"layer-3","term":"Layer 3","definition":"OSI network layer: moves packets between IP networks.","example":"A router chooses where an IP packet should go.","category":"Layers, frames, and transport","level":"foundation"},{"id":"layer-4","term":"Layer 4","definition":"OSI transport layer: delivers application data through protocols such as TCP and UDP.","example":"TCP port 443 identifies a transport endpoint for HTTPS traffic.","category":"Layers, frames, and transport","level":"foundation"},{"id":"layer-7","term":"Layer 7","definition":"OSI application layer: network functions used by applications.","example":"DNS and HTTP are usually discussed at Layer 7.","category":"Layers, frames, and transport","level":"foundation"},{"id":"encapsulation","term":"Encapsulation","definition":"Wrapping application data with headers as it moves down the protocol stack.","example":"An IP packet is placed inside an Ethernet frame.","category":"Layers, frames, and transport","level":"foundation"},{"id":"decapsulation","term":"Decapsulation","definition":"Removing headers when data moves up a receiving device's stack.","example":"A computer removes Ethernet and IP headers before handling TCP data.","category":"Layers, frames, and transport","level":"foundation"},{"id":"pdu","term":"PDU","definition":"Protocol data unit: the name for data at a particular layer.","example":"An Ethernet frame and an IP packet are different PDUs.","category":"Layers, frames, and transport","level":"foundation"},{"id":"frame","term":"Frame","definition":"A Layer 2 unit containing local delivery information and payload.","example":"A switch forwards Ethernet frames.","category":"Layers, frames, and transport","level":"foundation","detail":"A frame is the local delivery envelope. An Ethernet frame carries destination and source MAC addresses, an EtherType, payload such as an IP packet, and an error-detection field.","common_mistake":"The frame is not the same thing as the packet inside it."},{"id":"packet","term":"Packet","definition":"A Layer 3 unit containing IP source and destination information.","example":"A router forwards an IPv4 packet.","category":"Layers, frames, and transport","level":"foundation","detail":"An IP packet is the logical end-to-end delivery envelope that routers understand. The packet contains source and destination IP addresses and is wrapped inside a link-layer frame on each hop.","common_mistake":"When a router forwards a packet, the surrounding Ethernet frame changes; the packet does not become a new IP destination."},{"id":"segment","term":"Segment","definition":"A commonly used term for TCP's transport-layer data unit.","example":"TCP numbers bytes in a data stream and transmits segments.","category":"Layers, frames, and transport","level":"foundation"},{"id":"datagram","term":"Datagram","definition":"An independently handled message, often used for UDP or IP traffic.","example":"DNS queries often travel in UDP datagrams.","category":"Layers, frames, and transport","level":"foundation"},{"id":"payload","term":"Payload","definition":"The useful data carried inside a protocol wrapper.","example":"An Ethernet frame can carry an IP packet as its payload.","category":"Layers, frames, and transport","level":"foundation"},{"id":"header","term":"Header","definition":"Control information attached ahead of the payload.","example":"The IPv4 header contains source and destination IP addresses.","category":"Layers, frames, and transport","level":"foundation"},{"id":"trailer","term":"Trailer","definition":"Information appended after a payload, often for error detection.","example":"Ethernet's frame check sequence appears at the end.","category":"Layers, frames, and transport","level":"foundation"},{"id":"fcs","term":"FCS","definition":"Frame check sequence: bits at the end of an Ethernet frame used to detect corruption.","example":"A bad FCS indicates a damaged received frame.","category":"Layers, frames, and transport","level":"foundation"},{"id":"mac-address","term":"MAC address","definition":"A link-layer address used for delivery on an Ethernet network.","example":"A switch learns that a MAC address is reachable through port 5.","category":"Layers, frames, and transport","level":"foundation","detail":"A MAC address labels a network interface for local-link delivery. Switches use MAC forwarding tables, and Ethernet frames carry source and destination MAC addresses. Across a router, the Ethernet MAC addresses usually change to match the next hop.","common_mistake":"Knowing a remote destination's MAC is not what makes routing across the internet work."},{"id":"unicast","term":"Unicast","definition":"Traffic sent toward one intended receiver.","example":"A laptop sends a unicast packet to a web server.","category":"Layers, frames, and transport","level":"foundation"},{"id":"broadcast","term":"Broadcast","definition":"Traffic sent to all devices in a broadcast domain.","example":"An ARP request is typically broadcast on Ethernet.","category":"Layers, frames, and transport","level":"foundation"},{"id":"multicast","term":"Multicast","definition":"Traffic addressed to a group of interested receivers.","example":"Some routing protocols communicate using multicast addresses.","category":"Layers, frames, and transport","level":"foundation"},{"id":"ethertype","term":"EtherType","definition":"A field in an Ethernet frame identifying its carried protocol.","example":"0x0800 indicates IPv4 in common Ethernet framing.","category":"Layers, frames, and transport","level":"foundation"},{"id":"tcp","term":"TCP","definition":"Transmission Control Protocol: connection-oriented transport with acknowledgments and retransmission.","example":"Web browsing commonly uses TCP for reliable delivery.","category":"Layers, frames, and transport","level":"foundation","detail":"TCP numbers data, uses acknowledgments, adapts its sending rate and retransmits losses. This is excellent for reliably downloading a document, but retransmission can add delays when an application values freshness more than completeness.","common_mistake":"TCP does not guarantee that an application will receive data instantly or that every network packet arrives in order."},{"id":"udp","term":"UDP","definition":"User Datagram Protocol: connectionless transport with little delivery machinery.","example":"Live voice applications often use UDP to avoid retransmission delays.","category":"Layers, frames, and transport","level":"foundation","detail":"UDP provides datagrams without building reliable ordered delivery into the transport itself. Applications such as live voice or some games can choose how to handle late or missing packets.","common_mistake":"UDP does not mean every UDP application is insecure or unreliable; applications can implement their own protections."},{"id":"port-number","term":"Port number","definition":"A transport-layer number that identifies an application endpoint.","example":"HTTPS commonly uses TCP port 443.","category":"Layers, frames, and transport","level":"foundation"},{"id":"socket","term":"Socket","definition":"A software endpoint defined by an IP address, transport protocol, and port.","example":"A browser opens a TCP socket to a website.","category":"Layers, frames, and transport","level":"foundation"},{"id":"three-way-handshake","term":"Three-way handshake","definition":"TCP's process of establishing a connection using SYN, SYN-ACK, and ACK.","example":"A browser completes a TCP handshake before sending HTTP over TCP.","category":"Layers, frames, and transport","level":"foundation"},{"id":"syn","term":"SYN","definition":"TCP flag used to initiate or synchronize connection sequence numbers.","example":"The first TCP handshake message has SYN set.","category":"Layers, frames, and transport","level":"foundation"},{"id":"ack","term":"ACK","definition":"TCP acknowledgment information confirming received data or connection steps.","example":"A sender uses ACKs to decide what data needs retransmission.","category":"Layers, frames, and transport","level":"foundation"},{"id":"retransmission","term":"Retransmission","definition":"Sending data again because delivery or acknowledgment was missing.","example":"TCP retransmits lost data after detecting a loss.","category":"Layers, frames, and transport","level":"foundation"},{"id":"window-size","term":"Window size","definition":"An amount of data a TCP receiver or sender allows in flight.","example":"A larger receive window can help a high-latency file transfer.","category":"Layers, frames, and transport","level":"foundation"},{"id":"flow-control","term":"Flow control","definition":"A mechanism that prevents a sender from overwhelming a receiver.","example":"TCP's receive window advertises how much data the receiver can accept.","category":"Layers, frames, and transport","level":"foundation"},{"id":"congestion-control","term":"Congestion control","definition":"Techniques for limiting traffic when the network becomes overloaded.","example":"TCP may slow down when it detects packet loss.","category":"Layers, frames, and transport","level":"foundation"},{"id":"handshake","term":"Handshake","definition":"An initial exchange that sets up a session or agrees on parameters.","example":"TLS also performs a handshake before encrypted data flows.","category":"Layers, frames, and transport","level":"foundation"},{"id":"ip-address","term":"IP address","definition":"A logical address used to identify interfaces and route traffic between networks.","example":"192.168.10.20 can identify a host interface on a private LAN.","category":"IPv4 and subnetting","level":"ccna","detail":"An IP address is a logical location in a network, like a street address that can change when a device moves. Combined with a prefix, it tells the host which destinations are local and which need a router.","common_mistake":"An IP address is not the same as a MAC address and is not guaranteed to be permanently tied to a device."},{"id":"ipv4","term":"IPv4","definition":"The 32-bit version of Internet Protocol using dotted-decimal addresses.","example":"192.168.1.5 is an IPv4 address.","category":"IPv4 and subnetting","level":"ccna","detail":"IPv4 has 32-bit addresses. Public space is limited; private ranges and address translation are common on home and business networks. Learn address/mask interpretation before studying complex routes.","common_mistake":"A private address such as 192.168.1.5 is not generally routable directly across the public internet."},{"id":"octet","term":"Octet","definition":"A group of eight bits, often one dotted part of an IPv4 address.","example":"In 192.168.1.5, the number 168 is one octet.","category":"IPv4 and subnetting","level":"ccna"},{"id":"subnet","term":"Subnet","definition":"A portion of an IP network identified by a prefix.","example":"192.168.10.0/24 represents one IPv4 subnet.","category":"IPv4 and subnetting","level":"ccna"},{"id":"subnet-mask","term":"Subnet mask","definition":"A value indicating which IPv4 address bits describe the network.","example":"255.255.255.0 corresponds to a /24 prefix.","category":"IPv4 and subnetting","level":"ccna","detail":"The mask separates network bits from host bits in an IPv4 address. It is the reason 192.168.10.10/24 treats 192.168.10.99 as local, but 192.168.11.99 as remote. Subnetting is about binary bit boundaries, not just comparing the dots by eye.","common_mistake":"The mask is not a separate unique address assigned to a host."},{"id":"cidr","term":"CIDR","definition":"Classless inter-domain routing: using slash prefixes instead of fixed address classes.","example":"192.168.10.0/24 uses CIDR notation.","category":"IPv4 and subnetting","level":"ccna","detail":"A slash such as /24 means the first 24 bits of the 32-bit IPv4 address identify the network. A /26 leaves 6 host bits, producing 64 total addresses, while a /24 leaves 8 host bits, producing 256 total addresses.","common_mistake":"Do not assume every subnet has 256 usable host addresses; the prefix changes the size."},{"id":"prefix-length","term":"Prefix length","definition":"The number of leading bits identifying an IP network.","example":"The /24 in 192.168.1.0/24 means 24 network bits.","category":"IPv4 and subnetting","level":"ccna"},{"id":"network-address","term":"Network address","definition":"The address whose host bits are zero for an IPv4 subnet.","example":"192.168.1.0 is the network address for 192.168.1.0/24.","category":"IPv4 and subnetting","level":"ccna"},{"id":"broadcast-address","term":"Broadcast address","definition":"The highest IPv4 address in a conventional subnet, used for subnet broadcast.","example":"192.168.1.255 is the broadcast address for 192.168.1.0/24.","category":"IPv4 and subnetting","level":"ccna"},{"id":"usable-host-address","term":"Usable host address","definition":"An IP address available for assignment to an endpoint in a conventional subnet.","example":"192.168.1.42 is usable in 192.168.1.0/24.","category":"IPv4 and subnetting","level":"ccna"},{"id":"private-ipv4","term":"Private IPv4","definition":"IPv4 address space reserved for private networks and not routed publicly on the internet.","example":"10.0.0.7 is private IPv4 space.","category":"IPv4 and subnetting","level":"ccna"},{"id":"public-ipv4","term":"Public IPv4","definition":"An IPv4 address that can be routed on the public internet, subject to policy.","example":"A public website's server has an internet-routable address.","category":"IPv4 and subnetting","level":"ccna"},{"id":"apipa","term":"APIPA","definition":"Automatic private IP addressing: Windows term for a self-assigned 169.254/16 address.","example":"A PC may show 169.254.x.x if it cannot get DHCP configuration.","category":"IPv4 and subnetting","level":"ccna"},{"id":"loopback-address","term":"Loopback address","definition":"An address that refers back to the same device.","example":"127.0.0.1 means the local machine for IPv4.","category":"IPv4 and subnetting","level":"ccna"},{"id":"default-gateway","term":"Default gateway","definition":"A router address used when a host must send traffic outside its local subnet.","example":"A PC sends internet-bound traffic to 192.168.1.1.","category":"IPv4 and subnetting","level":"ccna","detail":"The default gateway is the local router interface a host uses when it has no more specific route to a destination. A host sends the first frame to the gateway's MAC, but the packet still names the actual remote destination IP.","common_mistake":"A default gateway is normally needed for off-subnet traffic, not to communicate with a neighbor in the same subnet."},{"id":"next-hop","term":"Next hop","definition":"The immediate router or neighbor that receives a forwarded packet.","example":"A route may send traffic to 10.1.1.1 as its next hop.","category":"IPv4 and subnetting","level":"ccna"},{"id":"arp","term":"ARP","definition":"Address Resolution Protocol: finds a local IPv4 next-hop MAC address.","example":"A PC broadcasts an ARP request for its gateway IP.","category":"IPv4 and subnetting","level":"ccna","detail":"When a host knows the IPv4 address of a local destination or next-hop router but lacks its MAC address, it typically broadcasts an ARP request. The owner replies, and the mapping is cached for later frames.","common_mistake":"ARP finds the local next-hop MAC, not the MAC address of every remote internet server."},{"id":"arp-table","term":"ARP table","definition":"A cache of IPv4-to-MAC mappings on a host or router.","example":"A device remembers its gateway's MAC in its ARP table.","category":"IPv4 and subnetting","level":"ccna"},{"id":"gratuitous-arp","term":"Gratuitous ARP","definition":"An ARP announcement about an address that was not requested.","example":"A device may announce a new IP-to-MAC mapping after failover.","category":"IPv4 and subnetting","level":"ccna"},{"id":"nat","term":"NAT","definition":"Network address translation: rewrites IP addresses as traffic passes a translation device.","example":"A home router translates private addresses to a public one.","category":"IPv4 and subnetting","level":"ccna","detail":"A NAT device rewrites IP address fields. PAT commonly lets many private hosts share one public IPv4 address by tracking ports; a session table keeps return traffic matched to the right inside host.","common_mistake":"NAT is address translation, not a substitute for a correctly designed firewall policy."},{"id":"pat","term":"PAT","definition":"Port address translation: many inside connections can share one translated address using ports.","example":"Two laptops browse through the same public IP with different ports.","category":"IPv4 and subnetting","level":"ccna"},{"id":"static-nat","term":"Static NAT","definition":"A fixed one-to-one IP address translation.","example":"A router might permanently map one internal server to one public IP.","category":"IPv4 and subnetting","level":"ccna"},{"id":"dynamic-nat","term":"Dynamic NAT","definition":"An address translation allocated from a pool when needed.","example":"An inside host temporarily uses an available public address.","category":"IPv4 and subnetting","level":"ccna"},{"id":"default-route","term":"Default route","definition":"A fallback route used when no more specific route matches.","example":"0.0.0.0/0 often points toward an internet provider.","category":"IPv4 and subnetting","level":"ccna"},{"id":"longest-prefix-match","term":"Longest prefix match","definition":"A router choosing the matching route with the most specific network prefix.","example":"A /24 route wins over a matching /16 route.","category":"IPv4 and subnetting","level":"ccna"},{"id":"summarization","term":"Summarization","definition":"Combining multiple routes into one broader advertised prefix.","example":"Four adjacent /24 networks might be represented by one /22.","category":"IPv4 and subnetting","level":"ccna"},{"id":"supernet","term":"Supernet","definition":"A larger network prefix that covers smaller networks.","example":"10.0.0.0/16 covers multiple 10.0.x.0/24 subnets.","category":"IPv4 and subnetting","level":"ccna"},{"id":"vlsm","term":"VLSM","definition":"Variable length subnet masking: using different prefix sizes in one address plan.","example":"A /30 link and a /24 user LAN can use addresses from one larger block.","category":"IPv4 and subnetting","level":"ccna"},{"id":"wildcard-mask","term":"Wildcard mask","definition":"A mask that marks bits to ignore during certain Cisco matching rules.","example":"0.0.0.255 matches any last octet for a /24 in a standard ACL.","category":"IPv4 and subnetting","level":"ccna"},{"id":"ipv6","term":"IPv6","definition":"The 128-bit version of Internet Protocol, written in hexadecimal groups.","example":"2001:db8::1 is an example IPv6 address.","category":"IPv6","level":"ccna","detail":"IPv6 has 128-bit addresses, usually written as eight hexadecimal groups with optional compression. Local communication uses link-local addresses and Neighbor Discovery; routers can advertise prefixes to hosts.","common_mistake":"IPv6 does not use ARP; it uses Neighbor Discovery messages."},{"id":"dual-stack","term":"Dual stack","definition":"Running IPv4 and IPv6 together on the same network.","example":"A website can be reached using either IP version.","category":"IPv6","level":"ccna"},{"id":"link-local-address","term":"Link-local address","definition":"An address valid only on the local link.","example":"An IPv6 router may have a fe80:: address used by nearby devices.","category":"IPv6","level":"ccna"},{"id":"global-unicast-address","term":"Global unicast address","definition":"An IPv6 address intended for routing beyond the local link.","example":"2001:db8:1::10 is documentation-style global unicast notation.","category":"IPv6","level":"ccna"},{"id":"unique-local-address","term":"Unique local address","definition":"An IPv6 address from private-use fc00::/7 space, commonly fd00::/8 locally assigned.","example":"An organization may number internal-only interfaces with fd12:: addresses.","category":"IPv6","level":"ccna"},{"id":"anycast","term":"Anycast","definition":"The same address assigned to multiple devices; routing chooses one reachable instance.","example":"DNS services may use anycast servers in many cities.","category":"IPv6","level":"ccna"},{"id":"slaac","term":"SLAAC","definition":"Stateless address autoconfiguration: IPv6 hosts generate addresses from router advertisements.","example":"A laptop makes an IPv6 address without a stateful address lease.","category":"IPv6","level":"ccna"},{"id":"dhcpv6","term":"DHCPv6","definition":"A protocol used to deliver IPv6 addressing or other configuration information.","example":"A router or server gives clients DNS settings through DHCPv6.","category":"IPv6","level":"ccna"},{"id":"neighbor-discovery","term":"Neighbor Discovery","definition":"IPv6's set of ICMPv6 messages for neighbor, router, and address discovery.","example":"An IPv6 host learns the router's link-layer address using neighbor solicitation.","category":"IPv6","level":"ccna"},{"id":"ndp","term":"NDP","definition":"Short for Neighbor Discovery Protocol, an IPv6 neighbor discovery process.","example":"NDP performs roles similar to ARP and more in IPv6.","category":"IPv6","level":"ccna"},{"id":"neighbor-solicitation","term":"Neighbor Solicitation","definition":"An ICMPv6 request to discover a neighbor or check address uniqueness.","example":"A host asks who owns a particular IPv6 address.","category":"IPv6","level":"ccna"},{"id":"neighbor-advertisement","term":"Neighbor Advertisement","definition":"An ICMPv6 response announcing neighbor information.","example":"A router replies with its link-layer address.","category":"IPv6","level":"ccna"},{"id":"router-advertisement","term":"Router Advertisement","definition":"An ICMPv6 message announcing a router and network prefixes.","example":"A laptop receives an RA before creating a SLAAC address.","category":"IPv6","level":"ccna"},{"id":"router-solicitation","term":"Router Solicitation","definition":"An ICMPv6 message asking routers to send advertisements.","example":"A newly joined laptop requests router information promptly.","category":"IPv6","level":"ccna"},{"id":"eui-64","term":"EUI-64","definition":"A method for constructing an IPv6 interface identifier from a MAC address.","example":"A device may derive part of an IPv6 address from its Ethernet identifier.","category":"IPv6","level":"ccna"},{"id":"ipv6-prefix","term":"IPv6 prefix","definition":"The leading part of an IPv6 address defining a network.","example":"2001:db8:1:10::/64 identifies a subnet prefix.","category":"IPv6","level":"ccna"},{"id":"icmpv6","term":"ICMPv6","definition":"Control messages for IPv6 errors, echo tests and neighbor discovery.","example":"IPv6 ping uses ICMPv6 echo messages.","category":"IPv6","level":"ccna"},{"id":"ra-guard","term":"RA Guard","definition":"A switch security feature that blocks unwanted IPv6 router advertisements.","example":"An access switch can prevent a rogue host announcing itself as a router.","category":"IPv6","level":"ccna"},{"id":"dad","term":"DAD","definition":"Duplicate address detection: an IPv6 host checks whether its chosen address is already used.","example":"A laptop tests an IPv6 address before assigning it.","category":"IPv6","level":"ccna"},{"id":"mac-address-table","term":"MAC address table","definition":"A switch's learned map of MAC addresses to ports.","example":"The switch knows device A is on Gi0/3.","category":"Switching","level":"ccna"},{"id":"cam-table","term":"CAM table","definition":"Content-addressable memory table; often used for switch MAC forwarding entries.","example":"A switch consults CAM entries when forwarding frames.","category":"Switching","level":"ccna"},{"id":"flooding","term":"Flooding","definition":"Sending a frame out multiple eligible ports because its destination is unknown or broadcast.","example":"An unknown destination MAC makes a switch flood a frame within the VLAN.","category":"Switching","level":"ccna"},{"id":"broadcast-domain","term":"Broadcast domain","definition":"A group of devices that receive each other's Layer 2 broadcasts.","example":"Two separate VLANs normally form two broadcast domains.","category":"Switching","level":"ccna"},{"id":"collision-domain","term":"Collision domain","definition":"A portion of shared media where simultaneous transmissions could collide.","example":"Each full-duplex switched Ethernet port avoids classic collisions.","category":"Switching","level":"ccna"},{"id":"vlan","term":"VLAN","definition":"Virtual LAN: a logical Layer 2 group on a switch.","example":"Accounting and guest devices can use separate VLANs.","category":"Switching","level":"ccna","detail":"A VLAN creates a separate logical Layer 2 broadcast domain even when devices share switches and cables. A host in VLAN 10 will not automatically reach VLAN 20; traffic between IP subnets needs a routing function and permitted policies.","common_mistake":"Creating a VLAN does not by itself create an IP subnet or a default gateway."},{"id":"vlan-id","term":"VLAN ID","definition":"A numerical identifier for a VLAN.","example":"VLAN 20 may hold office printers.","category":"Switching","level":"ccna"},{"id":"access-port","term":"Access port","definition":"A switch port carrying traffic for one VLAN without an 802.1Q tag to its endpoint.","example":"A desktop PC plugs into an access port in VLAN 10.","category":"Switching","level":"ccna"},{"id":"trunk-port","term":"Trunk port","definition":"A link designed to carry multiple VLANs, typically with tags.","example":"A switch-to-switch trunk carries VLANs 10 and 20.","category":"Switching","level":"ccna","detail":"A trunk carries traffic belonging to multiple VLANs between devices. In standard 802.1Q operation, frames generally receive a tag identifying the VLAN; native VLAN handling needs particular attention.","common_mistake":"A trunk port is not simply a faster port or a link reserved for internet traffic."},{"id":"802-1q","term":"802.1Q","definition":"An IEEE mechanism for adding a VLAN tag to Ethernet frames.","example":"A trunk marks traffic so the next switch knows its VLAN.","category":"Switching","level":"ccna"},{"id":"native-vlan","term":"Native VLAN","definition":"A VLAN whose frames are generally untagged on an 802.1Q trunk by default.","example":"A native VLAN mismatch can create unexpected traffic handling.","category":"Switching","level":"ccna"},{"id":"inter-vlan-routing","term":"Inter-VLAN routing","definition":"Routing between different VLAN IP subnets.","example":"A Layer 3 switch can let VLAN 10 reach VLAN 20 under policy.","category":"Switching","level":"ccna"},{"id":"svi","term":"SVI","definition":"Switched virtual interface: a Layer 3 interface associated with a VLAN.","example":"Interface VLAN 10 can be the default gateway for devices in that VLAN.","category":"Switching","level":"ccna"},{"id":"router-on-a-stick","term":"Router-on-a-stick","definition":"One router physical interface using subinterfaces to route multiple VLANs.","example":"A router connects to a switch over one 802.1Q trunk.","category":"Switching","level":"ccna"},{"id":"stp","term":"STP","definition":"Spanning Tree Protocol: prevents Layer 2 loops by logically blocking redundant links.","example":"STP disables one redundant switch path until needed.","category":"Switching","level":"ccna","detail":"Redundant switch links provide resilience but can create catastrophic Layer 2 loops. Spanning Tree picks a loop-free active path and blocks other paths until conditions change. Root selection matters for the paths traffic takes.","common_mistake":"STP does not eliminate the need to design a sensible redundant topology."},{"id":"rstp","term":"RSTP","definition":"Rapid Spanning Tree Protocol: a faster-converging evolution of STP.","example":"A redundant link can become active more quickly after failure.","category":"Switching","level":"ccna"},{"id":"rapid-pvst","term":"Rapid PVST+","definition":"Cisco per-VLAN implementation of rapid spanning tree.","example":"VLANs may select different root switches.","category":"Switching","level":"ccna"},{"id":"root-bridge","term":"Root bridge","definition":"The switch chosen as the reference point for spanning tree paths.","example":"Other switches calculate best paths toward the root bridge.","category":"Switching","level":"ccna"},{"id":"bpdu","term":"BPDU","definition":"Bridge protocol data unit: messages switches exchange to run spanning tree.","example":"STP switches send BPDUs to elect a root.","category":"Switching","level":"ccna"},{"id":"portfast","term":"PortFast","definition":"A switch feature allowing suitable edge ports to enter forwarding quickly.","example":"A PC access port can become active without standard STP delay.","category":"Switching","level":"ccna"},{"id":"bpdu-guard","term":"BPDU Guard","definition":"A feature that can disable an edge port if unexpected spanning-tree BPDUs arrive.","example":"A user plugging a switch into a protected edge port triggers guard.","category":"Switching","level":"ccna"},{"id":"root-guard","term":"Root Guard","definition":"A feature that prevents a port from accepting a superior root-bridge role.","example":"An access switch cannot unexpectedly become the spanning-tree root through that port.","category":"Switching","level":"ccna"},{"id":"loop-guard","term":"Loop Guard","definition":"A feature that helps prevent certain failures from creating Layer 2 loops.","example":"A switch protects a non-designated path when expected BPDUs stop arriving.","category":"Switching","level":"ccna"},{"id":"etherchannel","term":"EtherChannel","definition":"Bundling multiple physical Ethernet links into one logical link.","example":"Two switch uplinks operate as one channel.","category":"Switching","level":"ccna"},{"id":"lacp","term":"LACP","definition":"Link Aggregation Control Protocol: negotiates membership in a link bundle.","example":"Two switches form a port channel using LACP.","category":"Switching","level":"ccna","detail":"LACP lets two devices negotiate several physical links as one logical port channel. The members must have compatible configuration, and a single flow may still be pinned to one member by hashing.","common_mistake":"Two bundled 1 Gbps links do not always make one individual file transfer run at 2 Gbps."},{"id":"port-channel","term":"Port channel","definition":"The logical interface representing a bundled Ethernet link.","example":"Port-channel 1 carries traffic over two physical cables.","category":"Switching","level":"ccna"},{"id":"cdp","term":"CDP","definition":"Cisco Discovery Protocol: tells neighboring Cisco devices information about each other.","example":"A switch learns a connected Cisco router's interface name.","category":"Switching","level":"ccna"},{"id":"lldp","term":"LLDP","definition":"Link Layer Discovery Protocol: vendor-neutral neighbor information exchange.","example":"A switch learns the identity of a nearby VoIP phone.","category":"Switching","level":"ccna"},{"id":"dhcp-snooping","term":"DHCP snooping","definition":"A switch security feature that filters untrusted DHCP replies and builds bindings.","example":"A rogue DHCP server on an office port can be blocked.","category":"Switching","level":"ccna"},{"id":"dai","term":"DAI","definition":"Dynamic ARP Inspection: checks ARP packets against trusted information.","example":"A switch rejects suspicious ARP messages claiming the gateway IP.","category":"Switching","level":"ccna"},{"id":"port-security","term":"Port security","definition":"A switch feature that restricts MAC addresses permitted on a port.","example":"A port may allow only one known workstation MAC.","category":"Switching","level":"ccna"},{"id":"routing-table","term":"Routing table","definition":"A router's list of known destination prefixes and forwarding information.","example":"A router checks its table before sending a packet onward.","category":"Routing and network control","level":"ccna"},{"id":"fib","term":"FIB","definition":"Forwarding information base: a table optimized for fast actual packet forwarding.","example":"Hardware can use FIB entries rather than redoing every route calculation.","category":"Routing and network control","level":"ccna"},{"id":"rib","term":"RIB","definition":"Routing information base: the routes a router has learned and selected.","example":"A routing process updates the RIB after learning better paths.","category":"Routing and network control","level":"ccna"},{"id":"control-plane","term":"Control plane","definition":"The functions that decide network paths and learn topology.","example":"OSPF runs in the control plane.","category":"Routing and network control","level":"ccna"},{"id":"data-plane","term":"Data plane","definition":"The functions that forward user traffic using chosen paths.","example":"A switch ASIC moves packets using installed forwarding entries.","category":"Routing and network control","level":"ccna"},{"id":"management-plane","term":"Management plane","definition":"Functions for monitoring and changing network devices.","example":"SSH and SNMP are used for management.","category":"Routing and network control","level":"ccna"},{"id":"static-route","term":"Static route","definition":"A route configured manually by an administrator.","example":"A small branch router may use a fixed route to headquarters.","category":"Routing and network control","level":"ccna"},{"id":"dynamic-routing","term":"Dynamic routing","definition":"Routers exchanging information to learn routes automatically.","example":"OSPF updates paths when a link fails.","category":"Routing and network control","level":"ccna"},{"id":"administrative-distance","term":"Administrative distance","definition":"A local preference ranking between sources of routes.","example":"A router may prefer a static route over an OSPF route for the same prefix.","category":"Routing and network control","level":"ccna"},{"id":"metric","term":"Metric","definition":"A value a routing protocol uses to compare possible paths.","example":"OSPF assigns cost to paths.","category":"Routing and network control","level":"ccna"},{"id":"convergence","term":"Convergence","definition":"The time/process for network devices to agree on new paths after a change.","example":"Routing converges after an uplink goes down.","category":"Routing and network control","level":"ccna"},{"id":"igp","term":"IGP","definition":"Interior gateway protocol: routing inside an organization.","example":"OSPF and EIGRP are IGPs.","category":"Routing and network control","level":"ccna"},{"id":"egp","term":"EGP","definition":"Exterior gateway protocol: routing between routing domains.","example":"BGP is commonly called the exterior gateway routing protocol.","category":"Routing and network control","level":"ccna"},{"id":"ospf","term":"OSPF","definition":"Open Shortest Path First: link-state routing that calculates paths using topology information.","example":"Routers exchange link-state information and compute best paths.","category":"Routing and network control","level":"ccna","detail":"OSPF is a link-state routing protocol. Neighboring routers share topology information, maintain a link-state database, then run a shortest-path calculation. Troubleshooting starts with whether neighbors form, then whether routes reach the routing table.","common_mistake":"An OSPF neighbor being present does not automatically mean every route is correctly advertised or preferred."},{"id":"ospfv2","term":"OSPFv2","definition":"An OSPF version widely used for IPv4 routing.","example":"An OSPFv2 neighbor helps advertise IPv4 networks.","category":"Routing and network control","level":"ccna"},{"id":"ospfv3","term":"OSPFv3","definition":"An OSPF version developed for IPv6 and extensible to multiple address families.","example":"Two routers establish OSPFv3 adjacency on their link.","category":"Routing and network control","level":"ccna"},{"id":"area","term":"Area","definition":"In OSPF, a grouping of routers and links that limits topology flooding.","example":"Area 0 is the OSPF backbone.","category":"Routing and network control","level":"ccna"},{"id":"area-0","term":"Area 0","definition":"The OSPF backbone area linking other areas in a multi-area design.","example":"A branch area's routes reach another area through the backbone.","category":"Routing and network control","level":"ccna"},{"id":"router-id","term":"Router ID","definition":"A 32-bit identifier used to distinguish a routing protocol speaker.","example":"OSPF router ID might be 1.1.1.1 regardless of interface addresses.","category":"Routing and network control","level":"ccna"},{"id":"neighbor-adjacency","term":"Neighbor adjacency","definition":"A relationship between routers that exchange routing information.","example":"Two OSPF neighbors reach Full state after synchronizing databases.","category":"Routing and network control","level":"ccna"},{"id":"lsa","term":"LSA","definition":"Link-state advertisement: a message describing topology or reachable networks for link-state routing.","example":"OSPF floods LSAs to update its view of the topology.","category":"Routing and network control","level":"ccna"},{"id":"lsdb","term":"LSDB","definition":"Link-state database: the collected topology descriptions in a link-state routing area.","example":"OSPF runs SPF calculations against its LSDB.","category":"Routing and network control","level":"ccna"},{"id":"spf","term":"SPF","definition":"Shortest path first: algorithm for computing best routes through a graph.","example":"OSPF uses a shortest-path calculation after topology changes.","category":"Routing and network control","level":"ccna"},{"id":"dr","term":"DR","definition":"Designated router: an OSPF role chosen on certain multiaccess network types.","example":"One OSPF router reduces adjacency overhead on a broadcast segment.","category":"Routing and network control","level":"ccna"},{"id":"bdr","term":"BDR","definition":"Backup designated router: replacement ready for a designated router.","example":"The BDR can take over if the DR disappears.","category":"Routing and network control","level":"ccna"},{"id":"eigrp","term":"EIGRP","definition":"Enhanced Interior Gateway Routing Protocol: Cisco-origin routing protocol using DUAL.","example":"A router tracks feasible backup paths with EIGRP.","category":"Routing and network control","level":"ccna"},{"id":"dual","term":"DUAL","definition":"Diffusing Update Algorithm: EIGRP's route-computation algorithm.","example":"DUAL helps EIGRP converge without routing loops.","category":"Routing and network control","level":"ccna"},{"id":"bgp","term":"BGP","definition":"Border Gateway Protocol: routing protocol that exchanges paths between autonomous systems and within them.","example":"An internet provider advertises reachable prefixes with BGP.","category":"Routing and network control","level":"ccna","detail":"BGP exchanges prefixes and path attributes, making policy central to route selection. It is used heavily between internet networks and inside large enterprises for sophisticated routing designs.","common_mistake":"BGP does not simply choose the path with the fewest physical routers every time."},{"id":"autonomous-system","term":"Autonomous system","definition":"A set of networks operated under a common routing policy and identifier.","example":"An internet provider has its own AS number.","category":"Routing and network control","level":"ccna"},{"id":"as-number","term":"AS number","definition":"Autonomous system identifier used in BGP.","example":"AS 64512 is from a private AS number range.","category":"Routing and network control","level":"ccna"},{"id":"ibgp","term":"iBGP","definition":"Internal BGP: BGP sessions inside the same autonomous system.","example":"Two routers in one AS exchange routes through iBGP.","category":"Routing and network control","level":"ccna"},{"id":"ebgp","term":"eBGP","definition":"External BGP: BGP sessions between different autonomous systems.","example":"A company peers with an internet provider over eBGP.","category":"Routing and network control","level":"ccna"},{"id":"bgp-path-attributes","term":"BGP path attributes","definition":"Metadata BGP uses to describe and select routes.","example":"AS_PATH helps show which autonomous systems a route traversed.","category":"Routing and network control","level":"ccna"},{"id":"local-preference","term":"Local preference","definition":"A BGP attribute used inside an AS to influence outbound path choice.","example":"A higher local preference may select the preferred ISP path.","category":"Routing and network control","level":"ccna"},{"id":"as-path","term":"AS_PATH","definition":"A BGP attribute listing autonomous systems the advertisement traversed.","example":"A router rejects routes containing its own AS in AS_PATH.","category":"Routing and network control","level":"ccna"},{"id":"med","term":"MED","definition":"Multi-exit discriminator: a BGP attribute suggesting a preferred entry link to an AS.","example":"One provider may compare MED values from the same neighboring AS.","category":"Routing and network control","level":"ccna"},{"id":"route-redistribution","term":"Route redistribution","definition":"Importing routes from one routing source into another.","example":"A router redistributes selected static routes into OSPF.","category":"Routing and network control","level":"ccna"},{"id":"route-filtering","term":"Route filtering","definition":"Accepting or advertising only routes that meet policy.","example":"A prefix list can prevent announcing internal-only networks.","category":"Routing and network control","level":"ccna"},{"id":"prefix-list","term":"Prefix list","definition":"A rule list matching network prefixes and lengths.","example":"An outbound prefix list can permit a particular /24.","category":"Routing and network control","level":"ccna"},{"id":"route-map","term":"Route map","definition":"A set of policy statements that can match and change routing information.","example":"A route map can set local preference for selected BGP routes.","category":"Routing and network control","level":"ccna"},{"id":"pbr","term":"PBR","definition":"Policy-based routing: selecting forwarding behavior with a policy other than only destination prefix.","example":"A company sends one application's traffic toward a special firewall.","category":"Routing and network control","level":"ccna"},{"id":"ecmp","term":"ECMP","definition":"Equal-cost multipath: using multiple equal-cost forwarding paths.","example":"A router spreads traffic across two equal OSPF routes.","category":"Routing and network control","level":"ccna"},{"id":"hsrp","term":"HSRP","definition":"Hot Standby Router Protocol: Cisco gateway redundancy using a virtual IP.","example":"Two routers share a virtual default gateway with active/standby roles.","category":"Routing and network control","level":"ccna"},{"id":"vrrp","term":"VRRP","definition":"Virtual Router Redundancy Protocol: standards-based redundant default gateway.","example":"One virtual gateway remains reachable if a router fails.","category":"Routing and network control","level":"ccna"},{"id":"fhrp","term":"FHRP","definition":"First-hop redundancy protocol: a family of ways to make the default gateway resilient.","example":"HSRP and VRRP are FHRPs.","category":"Routing and network control","level":"ccna"},{"id":"gre","term":"GRE","definition":"Generic Routing Encapsulation: a tunneling mechanism that carries packets through another network.","example":"An enterprise carries a routing protocol across a GRE tunnel.","category":"Routing and network control","level":"ccna"},{"id":"tunnel","term":"Tunnel","definition":"A virtual path that wraps one protocol inside another.","example":"Remote offices can connect through an encrypted tunnel.","category":"Routing and network control","level":"ccna"},{"id":"dhcp","term":"DHCP","definition":"Dynamic Host Configuration Protocol: automatically supplies host network settings.","example":"A laptop receives an IP address, mask, router and DNS setting.","category":"Services and applications","level":"ccna","detail":"DHCP helps a new client get its network settings. In classic IPv4 operation, the process is often summarized as Discover, Offer, Request, Acknowledge. The server leases an address and may also specify the router and DNS resolver.","common_mistake":"DHCP does not forward web traffic or resolve domain names."},{"id":"dhcp-lease","term":"DHCP lease","definition":"A time-limited assignment of an IP address by DHCP.","example":"A laptop renews its address before the lease expires.","category":"Services and applications","level":"ccna"},{"id":"dhcp-relay","term":"DHCP relay","definition":"A router function that forwards DHCP messages to a server on another network.","example":"An office VLAN uses a central DHCP server across a routed link.","category":"Services and applications","level":"ccna"},{"id":"dns","term":"DNS","definition":"Domain Name System: converts names and other records into useful network information.","example":"A resolver returns the IP address for a website name.","category":"Services and applications","level":"ccna","detail":"DNS is a distributed naming system, not a delivery route. Your browser may ask a resolver for an A or AAAA record, get an IP address, and then connect to that IP using other protocols. The answer may be cached.","common_mistake":"A successful DNS lookup does not prove the website service is running."},{"id":"dns-resolver","term":"DNS resolver","definition":"A server or program that looks up DNS answers for clients.","example":"Your laptop asks a configured resolver for a hostname.","category":"Services and applications","level":"ccna"},{"id":"dns-a-record","term":"DNS A record","definition":"A DNS record that maps a name to an IPv4 address.","example":"An A record might point example.com to 192.0.2.10.","category":"Services and applications","level":"ccna"},{"id":"dns-aaaa-record","term":"DNS AAAA record","definition":"A DNS record mapping a name to an IPv6 address.","example":"An AAAA record might point example.com to 2001:db8::10.","category":"Services and applications","level":"ccna"},{"id":"dns-cname-record","term":"DNS CNAME record","definition":"A DNS alias pointing one name to another name.","example":"www.example.com can be an alias of host.example.com.","category":"Services and applications","level":"ccna"},{"id":"dns-mx-record","term":"DNS MX record","definition":"A DNS record directing mail for a domain to a mail server.","example":"MX records identify where incoming email should go.","category":"Services and applications","level":"ccna"},{"id":"ttl","term":"TTL","definition":"Time to live: a limit on a packet's lifetime or how long a cached DNS record can be kept.","example":"A DNS record with TTL 300 can normally be cached for 300 seconds.","category":"Services and applications","level":"ccna"},{"id":"http","term":"HTTP","definition":"Hypertext Transfer Protocol: application protocol for exchanging web content.","example":"A browser requests a page using HTTP.","category":"Services and applications","level":"ccna"},{"id":"https","term":"HTTPS","definition":"HTTP protected with TLS encryption and authentication.","example":"A bank website uses HTTPS for protected traffic.","category":"Services and applications","level":"ccna"},{"id":"tls","term":"TLS","definition":"Transport Layer Security: encryption and authentication for many application connections.","example":"HTTPS uses TLS to protect browser-server data.","category":"Services and applications","level":"ccna"},{"id":"ssh","term":"SSH","definition":"Secure Shell: encrypted remote command-line access.","example":"An engineer safely logs into a switch with SSH.","category":"Services and applications","level":"ccna"},{"id":"telnet","term":"Telnet","definition":"Older unencrypted remote terminal protocol.","example":"Telnet credentials can be exposed on a captured link.","category":"Services and applications","level":"ccna"},{"id":"ftp","term":"FTP","definition":"File Transfer Protocol: an older file-transfer protocol without built-in secure transport.","example":"Do not use ordinary FTP for secrets over untrusted networks.","category":"Services and applications","level":"ccna"},{"id":"sftp","term":"SFTP","definition":"SSH File Transfer Protocol: transfers files over SSH.","example":"An admin securely uploads a configuration backup using SFTP.","category":"Services and applications","level":"ccna"},{"id":"scp","term":"SCP","definition":"Secure Copy Protocol: file transfer over an SSH connection.","example":"A router copies a file securely to a server using SCP.","category":"Services and applications","level":"ccna"},{"id":"ntp","term":"NTP","definition":"Network Time Protocol: keeps device clocks synchronized.","example":"Router logs are easier to compare when NTP is configured.","category":"Services and applications","level":"ccna"},{"id":"snmp","term":"SNMP","definition":"Simple Network Management Protocol: reads device status and may change managed values.","example":"A monitoring server polls an interface's counters with SNMP.","category":"Services and applications","level":"ccna"},{"id":"syslog","term":"Syslog","definition":"A standard method of recording and shipping device event messages.","example":"A router forwards failed-login events to a syslog server.","category":"Services and applications","level":"ccna"},{"id":"syslog-severity","term":"Syslog severity","definition":"A number describing how urgent a syslog message is, from 0 most severe to 7 debugging.","example":"Severity 3 indicates an error condition.","category":"Services and applications","level":"ccna"},{"id":"icmp","term":"ICMP","definition":"Internet Control Message Protocol: carries network errors and diagnostic messages.","example":"Ping uses ICMP echo request and reply.","category":"Services and applications","level":"ccna"},{"id":"ping","term":"Ping","definition":"A tool that tests whether a destination replies to network echo requests.","example":"Ping a gateway to confirm basic IP reachability.","category":"Services and applications","level":"ccna"},{"id":"traceroute","term":"Traceroute","definition":"A tool showing the approximate sequence of routers along a path.","example":"Traceroute helps locate a path break beyond your LAN.","category":"Services and applications","level":"ccna"},{"id":"aaa","term":"AAA","definition":"Authentication, authorization, accounting: confirming identity, permissions and activity.","example":"A company can centrally control network administrator logins.","category":"Security and wireless","level":"ccna"},{"id":"authentication","term":"Authentication","definition":"Checking who a user or device claims to be.","example":"A password or certificate can prove identity.","category":"Security and wireless","level":"ccna"},{"id":"authorization","term":"Authorization","definition":"Deciding what an authenticated identity may do.","example":"A help-desk account can view settings but not change them.","category":"Security and wireless","level":"ccna"},{"id":"accounting","term":"Accounting","definition":"Recording actions or use for audit and visibility.","example":"An AAA server records an administrator login.","category":"Security and wireless","level":"ccna"},{"id":"acl","term":"ACL","definition":"Access control list: ordered permit/deny rules used to filter traffic or match packets.","example":"An ACL blocks guests from a server subnet.","category":"Security and wireless","level":"ccna","detail":"ACL rules are evaluated in order, and the first matching permit or deny action usually decides the packet's fate. At the end of an IPv4 ACL is an implicit deny. Placement, direction and matching fields are as important as the rule text.","common_mistake":"A permit rule after an earlier matching deny will never be reached for that traffic."},{"id":"standard-acl","term":"Standard ACL","definition":"An IPv4 ACL primarily matching source IPv4 addresses.","example":"A standard ACL may allow only one management subnet.","category":"Security and wireless","level":"ccna"},{"id":"extended-acl","term":"Extended ACL","definition":"An IPv4 ACL that can match addresses, protocols and ports.","example":"An extended ACL permits DNS while denying other traffic.","category":"Security and wireless","level":"ccna"},{"id":"implicit-deny","term":"Implicit deny","definition":"The default rejection when traffic matches no permit statement in an ACL.","example":"Packets not allowed by any ACL entry are dropped.","category":"Security and wireless","level":"ccna"},{"id":"stateful-firewall","term":"Stateful firewall","definition":"A firewall that remembers connections and evaluates returning traffic in context.","example":"Replies to an outbound web session may be allowed automatically.","category":"Security and wireless","level":"ccna"},{"id":"zone-based-firewall","term":"Zone-based firewall","definition":"A firewall policy using logical groups of interfaces called zones.","example":"Traffic from a guest zone to an internal zone can be denied.","category":"Security and wireless","level":"ccna"},{"id":"vpn","term":"VPN","definition":"Virtual private network: a private-like connection across another network.","example":"An employee securely connects to an office over the internet.","category":"Security and wireless","level":"ccna"},{"id":"ipsec","term":"IPsec","definition":"A set of standards for protecting IP traffic, often used with VPNs.","example":"Two branch routers create an encrypted IPsec connection.","category":"Security and wireless","level":"ccna","detail":"IPsec protects IP traffic using negotiated security associations and encryption or integrity mechanisms. In a site-to-site VPN, two edge devices build a protected tunnel through an untrusted transport network.","common_mistake":"A VPN protects traffic between its tunnel endpoints; it does not automatically secure devices at either end."},{"id":"ike","term":"IKE","definition":"Internet Key Exchange: negotiates security settings and keys for IPsec.","example":"Two VPN peers use IKE before protected packets flow.","category":"Security and wireless","level":"ccna"},{"id":"encryption","term":"Encryption","definition":"Transforming readable information into ciphertext using a key.","example":"HTTPS encrypts data traveling across public networks.","category":"Security and wireless","level":"ccna"},{"id":"hash","term":"Hash","definition":"A fixed-length digest computed from data to support integrity checks.","example":"A downloaded file hash can help detect accidental changes.","category":"Security and wireless","level":"ccna"},{"id":"certificate","term":"Certificate","definition":"A signed digital document binding a public key to an identity.","example":"A website presents a certificate during TLS negotiation.","category":"Security and wireless","level":"ccna"},{"id":"pki","term":"PKI","definition":"Public key infrastructure: systems and policies that issue and trust digital certificates.","example":"Browsers trust recognized certificate authorities.","category":"Security and wireless","level":"ccna"},{"id":"radius","term":"RADIUS","definition":"A common centralized AAA protocol for network access and device logins.","example":"A wireless controller asks a RADIUS server to check credentials.","category":"Security and wireless","level":"ccna"},{"id":"tacacs","term":"TACACS+","definition":"A protocol often used for centralized administrative access to network devices.","example":"Cisco device commands can be authorized through TACACS+.","category":"Security and wireless","level":"ccna"},{"id":"802-1x","term":"802.1X","definition":"A standard for authenticating devices/users before network access.","example":"A corporate switch port requires employee credentials.","category":"Security and wireless","level":"ccna"},{"id":"port-based-authentication","term":"Port-based authentication","definition":"Deciding whether a device may use a switch or wireless link based on identity.","example":"An office port stays restricted until 802.1X succeeds.","category":"Security and wireless","level":"ccna"},{"id":"zero-trust","term":"Zero trust","definition":"A security approach that continually verifies access instead of trusting network location.","example":"An internal laptop still needs permission to reach sensitive systems.","category":"Security and wireless","level":"ccna"},{"id":"segmentation","term":"Segmentation","definition":"Dividing a network into separate trust or traffic groups.","example":"Guest Wi-Fi cannot freely reach finance servers.","category":"Security and wireless","level":"ccna"},{"id":"vulnerability","term":"Vulnerability","definition":"A weakness attackers might exploit.","example":"An unpatched switch service may contain a vulnerability.","category":"Security and wireless","level":"ccna"},{"id":"exploit","term":"Exploit","definition":"A method or code that takes advantage of a vulnerability.","example":"An attacker abuses an exposed service's defect.","category":"Security and wireless","level":"ccna"},{"id":"threat","term":"Threat","definition":"Something capable of causing harm to a system.","example":"A phishing campaign is a security threat.","category":"Security and wireless","level":"ccna"},{"id":"risk","term":"Risk","definition":"The combination of how likely a bad event is and how harmful it would be.","example":"An exposed management interface creates operational risk.","category":"Security and wireless","level":"ccna"},{"id":"wlan","term":"WLAN","definition":"Wireless local area network: a LAN using wireless communication.","example":"Office Wi-Fi is a WLAN.","category":"Security and wireless","level":"ccna"},{"id":"ssid","term":"SSID","definition":"The name a Wi-Fi network advertises to users.","example":"A phone selects the SSID Office-Guest.","category":"Security and wireless","level":"ccna"},{"id":"bssid","term":"BSSID","definition":"A Wi-Fi radio identifier, commonly its access point MAC address.","example":"Two access points can offer the same SSID with different BSSIDs.","category":"Security and wireless","level":"ccna"},{"id":"rf","term":"RF","definition":"Radio frequency: electromagnetic signals used for wireless communication.","example":"Wi-Fi uses radio frequencies in several bands.","category":"Security and wireless","level":"ccna"},{"id":"channel","term":"Channel","definition":"A defined slice of radio spectrum used for communication.","example":"Two nearby access points may use different channels to reduce interference.","category":"Security and wireless","level":"ccna"},{"id":"interference","term":"Interference","definition":"Unwanted signals that reduce communication quality.","example":"Nearby Wi-Fi devices competing on a channel can cause interference.","category":"Security and wireless","level":"ccna"},{"id":"rssi","term":"RSSI","definition":"Received signal strength indicator: an estimate of the radio signal level at a receiver.","example":"A weak RSSI can accompany unreliable wireless connections.","category":"Security and wireless","level":"ccna"},{"id":"snr","term":"SNR","definition":"Signal-to-noise ratio: how strong the wanted signal is compared with noise.","example":"Higher SNR usually permits better wireless performance.","category":"Security and wireless","level":"ccna"},{"id":"roaming","term":"Roaming","definition":"A client moving from one wireless access point to another.","example":"A phone stays on the same office Wi-Fi while walking between rooms.","category":"Security and wireless","level":"ccna"},{"id":"wpa2","term":"WPA2","definition":"A Wi-Fi security standard supporting strong encryption when configured correctly.","example":"A home router may offer WPA2-Personal.","category":"Security and wireless","level":"ccna"},{"id":"wpa3","term":"WPA3","definition":"A newer Wi-Fi security standard with improved protections over WPA2.","example":"A modern office may require WPA3-Enterprise.","category":"Security and wireless","level":"ccna"},{"id":"psk","term":"PSK","definition":"Pre-shared key: a shared secret used by devices to join protected Wi-Fi.","example":"A home Wi-Fi password acts as a shared key.","category":"Security and wireless","level":"ccna"},{"id":"captive-portal","term":"Captive portal","definition":"A sign-in or acceptance page shown before granting broader network access.","example":"A hotel prompts guests to accept terms.","category":"Security and wireless","level":"ccna"},{"id":"wireless-controller","term":"Wireless controller","definition":"A system that centrally manages multiple access points.","example":"IT uses a controller to configure many campus APs.","category":"Security and wireless","level":"ccna"},{"id":"cli","term":"CLI","definition":"Command-line interface: typed commands used to inspect or configure systems.","example":"An engineer enters show ip route in Cisco IOS.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"gui","term":"GUI","definition":"Graphical user interface: settings and controls shown as windows and buttons.","example":"A firewall web dashboard is a GUI.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"cisco-ios","term":"Cisco IOS","definition":"Cisco's network operating system family used on many routers and switches.","example":"The IOS CLI accepts show running-config.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"running-configuration","term":"Running configuration","definition":"The active set of Cisco device settings held in memory.","example":"A change takes effect in the running configuration.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"startup-configuration","term":"Startup configuration","definition":"Saved Cisco settings used at device startup.","example":"Copy running-config startup-config saves changes.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"privilege-mode","term":"Privilege mode","definition":"A Cisco CLI level that controls which operational commands you may run.","example":"The # prompt often indicates privileged EXEC mode.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"configuration-mode","term":"Configuration mode","definition":"A Cisco CLI context for changing device settings.","example":"configure terminal enters global configuration mode.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"show-command","term":"Show command","definition":"A Cisco IOS command that displays status or configuration.","example":"show interfaces displays counters and state.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"ping-test","term":"Ping test","definition":"A reachability check using echo requests and replies.","example":"Test the default gateway before testing the internet.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"packet-capture","term":"Packet capture","definition":"A recording of packets observed on an interface.","example":"Wireshark shows TCP handshakes in a capture.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"wireshark","term":"Wireshark","definition":"A packet analyzer that can display and filter traffic.","example":"Inspect DNS requests and replies in Wireshark.","category":"Operations, tools, and diagnostics","level":"ccna","detail":"Wireshark reveals captured packets and decodes protocol headers. Start by identifying an interface, applying a display filter and following a single conversation. Capture only traffic you own or are authorized to inspect.","common_mistake":"An encrypted HTTPS packet capture generally cannot reveal the protected web page content without appropriate keys."},{"id":"packet-tracer","term":"Packet Tracer","definition":"Cisco's teaching simulator for building and testing virtual networks.","example":"Create two switches and a router without purchasing hardware.","category":"Operations, tools, and diagnostics","level":"ccna","detail":"Packet Tracer simulates a subset of Cisco devices and network behaviors, making it ideal for early CCNA labs. Practice building a topology, configuring addressing and running show commands rather than only watching animated packets.","common_mistake":"A successful Packet Tracer lab does not prove that all real hardware features or CCIE scenarios are supported."},{"id":"gns3","term":"GNS3","definition":"A network emulation platform that runs software-based network devices.","example":"Build a practice topology using supported virtual appliances.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"cisco-modeling-labs","term":"Cisco Modeling Labs","definition":"Cisco's network simulation/emulation platform using virtual network images.","example":"Practice enterprise routing with licensed CML nodes.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"interface-counters","term":"Interface counters","definition":"Numbers showing traffic, drops and errors on a network port.","example":"Rising CRC errors suggest a physical link problem.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"duplex-mismatch","term":"Duplex mismatch","definition":"A link problem where two sides disagree about how to send and receive.","example":"A mismatched legacy port can show errors and poor throughput.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"speed-mismatch","term":"Speed mismatch","definition":"A link problem where the two sides do not establish a compatible speed.","example":"A cable problem may prevent a gigabit link from coming up.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"dns-lookup","term":"DNS lookup","definition":"A request to translate a name using DNS records.","example":"nslookup example.com asks a resolver for records.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"nslookup","term":"nslookup","definition":"A tool that requests DNS information.","example":"Use nslookup to check which IP a hostname resolves to.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"dig","term":"dig","definition":"A command-line tool for detailed DNS queries.","example":"dig example.com MX checks mail routing records.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"ipconfig","term":"ipconfig","definition":"Windows command for viewing and adjusting IP configuration.","example":"ipconfig /all lists addresses, gateways and DNS servers.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"ip-addr","term":"ip addr","definition":"Linux command to show or configure IP interface addresses.","example":"ip addr show lists assigned IPv4 and IPv6 addresses.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"ip-route","term":"ip route","definition":"Linux command to inspect or change route information.","example":"ip route show reveals the default route.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"tracert","term":"tracert","definition":"Windows command that traces the approximate route toward a destination.","example":"tracert example.com displays hop responses.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"show-ip-route","term":"show ip route","definition":"Cisco IOS command displaying the IPv4 routing table.","example":"Check show ip route after adding a static route.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"show-interfaces","term":"show interfaces","definition":"Cisco IOS command displaying interface state and counters.","example":"Look for errors and an administratively down state.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"show-vlan-brief","term":"show vlan brief","definition":"Cisco IOS command summarizing VLANs and access-port membership.","example":"Confirm whether port Gi0/5 is assigned to VLAN 20.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"show-mac-address-table","term":"show mac address-table","definition":"Cisco IOS command showing learned Ethernet MAC forwarding entries.","example":"See which switch port leads to a workstation.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"show-ip-ospf-neighbor","term":"show ip ospf neighbor","definition":"Cisco IOS command displaying OSPF neighbor states.","example":"Verify a neighbor reaches Full where expected.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"baseline","term":"Baseline","definition":"A record of normal performance used to spot abnormal behavior.","example":"Compare today's error count with a known healthy week.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"troubleshooting","term":"Troubleshooting","definition":"A systematic process for finding and correcting an observed problem.","example":"Check power and link before changing routing configuration.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"root-cause","term":"Root cause","definition":"The actual underlying reason a problem occurred.","example":"A damaged fiber patch cable is the root cause of repeated link drops.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"change-control","term":"Change control","definition":"A process for approving, documenting and reversing network changes.","example":"Schedule a routing change with a rollback plan.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"rollback","term":"Rollback","definition":"Restoring the previous working state after an unsuccessful change.","example":"Reapply last night's saved switch configuration.","category":"Operations, tools, and diagnostics","level":"ccna"},{"id":"api","term":"API","definition":"Application programming interface: a defined way software requests functions or data.","example":"An automation script reads switch inventory through an API.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"rest-api","term":"REST API","definition":"An API style commonly using HTTP methods and resources.","example":"A script requests /devices through HTTPS.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"json","term":"JSON","definition":"A structured text format for exchanging objects and lists.","example":"An API returns a JSON object with device names.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"yaml","term":"YAML","definition":"A human-friendly data format used for configuration.","example":"An Ansible playbook is often written in YAML.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"xml","term":"XML","definition":"A markup format that represents structured data using tagged elements.","example":"NETCONF can exchange configuration data in XML.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"ansible","term":"Ansible","definition":"An automation tool that executes repeatable tasks on devices.","example":"An Ansible playbook configures VLANs on several switches.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"playbook","term":"Playbook","definition":"A file describing ordered automation tasks.","example":"One playbook configures NTP on ten routers.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"idempotent","term":"Idempotent","definition":"An operation that can be repeated without continually changing its result.","example":"Applying the same desired VLAN configuration twice leaves the same state.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"netconf","term":"NETCONF","definition":"A protocol for reading and changing network configuration through structured operations.","example":"An automation client sends structured configuration to a router.","category":"Automation, architecture, and expert networking","level":"advanced","detail":"NETCONF is a structured management protocol, often over SSH, with operations to retrieve and modify configuration. Its data is commonly represented in XML and organized by YANG models.","common_mistake":"NETCONF is not a CLI screen-scraping tool; it offers structured programmatic operations."},{"id":"restconf","term":"RESTCONF","definition":"A REST-like interface for network device data modeled with YANG.","example":"A script updates a device interface configuration over HTTPS.","category":"Automation, architecture, and expert networking","level":"advanced","detail":"RESTCONF exposes YANG-modeled network data through HTTP-based operations. An automation program can retrieve interface state or modify configuration using well-defined resources.","common_mistake":"RESTCONF and a device's arbitrary web GUI are not interchangeable just because both use HTTP."},{"id":"yang","term":"YANG","definition":"A data modeling language defining structure and meaning of network configuration and state.","example":"A YANG model describes interface settings consistently.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"telemetry","term":"Telemetry","definition":"Measurements automatically sent or collected from systems.","example":"A router streams interface utilization to a dashboard.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"streaming-telemetry","term":"Streaming telemetry","definition":"A device pushing frequent structured measurements rather than waiting for occasional polls.","example":"A collector receives updated interface counters every second.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"snmp-polling","term":"SNMP polling","definition":"A monitoring system periodically requesting device metrics.","example":"A dashboard asks a switch for port utilization once a minute.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"sdn","term":"SDN","definition":"Software-defined networking: using software control to manage network behavior.","example":"A controller programs forwarding policies across devices.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"controller","term":"Controller","definition":"A central system that coordinates network devices or their configuration.","example":"A campus controller provisions access point settings.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"intent-based-networking","term":"Intent-based networking","definition":"Defining the desired network outcome and using software to implement or verify it.","example":"Declare that guests cannot reach payroll systems and check policy compliance.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"underlay","term":"Underlay","definition":"The physical or routed network that transports an overlay.","example":"IP routers provide connectivity beneath VXLAN tunnels.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"overlay","term":"Overlay","definition":"A virtual network built over another network.","example":"A VXLAN overlay connects workloads across routed infrastructure.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"vxlan","term":"VXLAN","definition":"Virtual extensible LAN: an encapsulation technology that carries Layer 2 segments over IP.","example":"Two data-center racks share a virtual segment across an IP fabric.","category":"Automation, architecture, and expert networking","level":"advanced","detail":"VXLAN wraps Layer 2 traffic in UDP/IP so a virtual Ethernet segment can span a routed network. VTEPs encapsulate and decapsulate this traffic at the edge of the overlay.","common_mistake":"VXLAN still depends on a healthy routed underlay."},{"id":"vtep","term":"VTEP","definition":"VXLAN tunnel endpoint: a device that encapsulates or decapsulates VXLAN traffic.","example":"A leaf switch operates as a VTEP for attached servers.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"evpn","term":"EVPN","definition":"Ethernet VPN: a BGP-based control-plane technology often used with VXLAN.","example":"EVPN distributes endpoint reachability across a fabric.","category":"Automation, architecture, and expert networking","level":"advanced","detail":"EVPN uses BGP to distribute reachability for Ethernet-based services and often complements VXLAN in data centers. Learn underlay reachability first, then encapsulation, then EVPN control-plane signaling.","common_mistake":"EVPN is not the same thing as VXLAN; they often work together in different roles."},{"id":"mpls","term":"MPLS","definition":"Multiprotocol label switching: forwarding traffic using short labels along a path.","example":"A provider carries customers' traffic across an MPLS core.","category":"Automation, architecture, and expert networking","level":"advanced","detail":"MPLS inserts labels that transit routers use for forwarding along provider or enterprise paths. It supports traffic engineering and service separation, including Layer 3 VPN designs.","common_mistake":"MPLS labels alone do not encrypt traffic."},{"id":"label-switching","term":"Label switching","definition":"Forwarding packets using a label rather than repeatedly relying only on the destination IP.","example":"An MPLS router swaps labels along an established path.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"vrf","term":"VRF","definition":"Virtual routing and forwarding: multiple separate routing tables on one device.","example":"A router isolates two customers with different VRFs.","category":"Automation, architecture, and expert networking","level":"advanced","detail":"VRF provides separate routing tables on one device so overlapping IP ranges or different customers can be isolated. Connections between VRFs require deliberate route leaking or another routing path.","common_mistake":"A VRF is not just a different VLAN; it separates Layer 3 routing contexts."},{"id":"vpnv4","term":"VPNv4","definition":"An address family used in MPLS L3VPN designs to carry customer IPv4 routes with route distinguishers.","example":"A provider exchanges customer routes without mixing their identities.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"route-distinguisher","term":"Route distinguisher","definition":"A value added to a route so overlapping VPN address spaces remain unique.","example":"Two customers both using 10.0.0.0/24 get distinct VPNv4 routes.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"route-target","term":"Route target","definition":"A BGP extended community controlling which VPN routes are imported or exported.","example":"A VRF imports only routes with permitted route targets.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"l3vpn","term":"L3VPN","definition":"Layer 3 virtual private network: provider-managed separation and routing for customers.","example":"A business connects branches through a carrier L3VPN.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"qos","term":"QoS","definition":"Quality of service: classifying and managing traffic under resource limits.","example":"Voice traffic may receive priority during congestion.","category":"Automation, architecture, and expert networking","level":"advanced","detail":"QoS classifies traffic and decides how a congested interface allocates finite capacity. Marking alone is not enough; queuing, shaping or policing policies must be designed and verified at the right points.","common_mistake":"QoS generally does not create new bandwidth; it decides how existing bandwidth is used."},{"id":"dscp","term":"DSCP","definition":"Differentiated services code point: an IP header marking used by QoS policies.","example":"Voice packets may carry a high-priority DSCP marking.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"cos","term":"CoS","definition":"Class of service: Layer 2 priority information, often from 802.1Q tags.","example":"A switch may map 802.1p priority into a QoS class.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"queuing","term":"Queuing","definition":"Placing packets into ordered waiting lines for transmission.","example":"A router services voice and bulk-data queues differently.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"shaping","term":"Shaping","definition":"Delaying traffic to keep its average rate under a configured limit.","example":"A router shapes traffic to fit a provider's contracted speed.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"policing","term":"Policing","definition":"Enforcing a traffic rate by marking or dropping excess packets.","example":"A service provider polices bursts beyond a purchased rate.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"high-availability","term":"High availability","definition":"Designing systems so a service stays reachable despite failures.","example":"Two routers and redundant links reduce single points of failure.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"failover","term":"Failover","definition":"Moving service to a backup when the active system fails.","example":"A standby gateway takes over after the active router dies.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"redundancy","term":"Redundancy","definition":"Extra components or paths that can replace failed ones.","example":"Two diverse internet uplinks provide redundancy.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"ecmp-hashing","term":"ECMP hashing","definition":"Using packet-header fields to assign flows across equal-cost paths.","example":"One application flow consistently uses a particular uplink.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"bfd","term":"BFD","definition":"Bidirectional Forwarding Detection: a fast mechanism for detecting loss of forwarding connectivity.","example":"A router notices a failed peer quickly and notifies routing protocols.","category":"Automation, architecture, and expert networking","level":"advanced","detail":"BFD quickly detects loss of forwarding connectivity between two endpoints. Routing protocols can use that signal to react faster than their usual timers would allow.","common_mistake":"BFD detects a path failure; it does not choose the replacement route by itself."},{"id":"udld","term":"UDLD","definition":"Unidirectional Link Detection: detecting a link that passes traffic only one way.","example":"UDLD can protect a switch fabric from a one-way fiber fault.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"span","term":"SPAN","definition":"Switched port analyzer: copying switch traffic to a monitor port.","example":"Send VLAN traffic to a Wireshark laptop for diagnosis.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"rspan","term":"RSPAN","definition":"Remote SPAN: carrying mirrored switch traffic across a dedicated VLAN.","example":"Capture traffic from a switch in another wiring closet.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"erspan","term":"ERSPAN","definition":"Encapsulated remote SPAN: tunneling mirrored traffic over IP.","example":"A monitoring server receives mirrored packets from a remote switch.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"multicast-routing","term":"Multicast routing","definition":"Forwarding one sender's traffic efficiently toward receivers that joined a group.","example":"Live video can reach many receivers without separate copies per receiver at every hop.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"igmp","term":"IGMP","definition":"Internet Group Management Protocol: IPv4 host messages for multicast group membership.","example":"A TV receiver joins an IPTV multicast group with IGMP.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"pim","term":"PIM","definition":"Protocol Independent Multicast: a router protocol for building multicast distribution paths.","example":"PIM routers construct a multicast tree between sources and receivers.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"multicast-tree","term":"Multicast tree","definition":"The network of branches used to deliver group traffic efficiently.","example":"A router replicates video only where receiver paths branch.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"fabric","term":"Fabric","definition":"A coordinated multi-switch topology designed as one scalable network system.","example":"A leaf-spine fabric connects racks with predictable paths.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"spine-leaf","term":"Spine-leaf","definition":"A data-center design where leaf switches connect to each spine switch.","example":"A server's leaf has several equal-length paths through spines.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"segment-routing","term":"Segment routing","definition":"A method of steering packets through a network using segments or instructions.","example":"A provider chooses a path for latency-sensitive services.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"sr-mpls","term":"SR-MPLS","definition":"Segment routing with MPLS labels encoding forwarding instructions.","example":"A provider steers flows through selected routers using label stacks.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"lisp","term":"LISP","definition":"Locator/ID Separation Protocol: separates endpoint identities from locations.","example":"A campus fabric can preserve an endpoint identity while its location changes.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"sd-access","term":"SD-Access","definition":"Cisco campus-fabric architecture providing policy-based segmentation and automation.","example":"A campus groups user access with centrally applied virtual networks.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"sd-wan","term":"SD-WAN","definition":"Software-defined WAN: centralized policies steering traffic across wide-area links.","example":"Branch traffic can choose MPLS or internet transport by application policy.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"ip-sla","term":"IP SLA","definition":"Cisco measurement feature that generates active probes of reachability or performance.","example":"A router tests if an upstream server responds before changing routes.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"agentic-ai","term":"Agentic AI","definition":"AI that can plan and carry out multiple tool-based steps with supervision and safeguards.","example":"An operations assistant may propose checks, collect logs and summarize a fault.","category":"Automation, architecture, and expert networking","level":"advanced","detail":"An AI agent can collect data and propose or carry out a multi-step troubleshooting workflow. Treat device output and logs as potentially untrusted, limit permissions, and require human approval for consequential changes.","common_mistake":"AI-generated configurations can be wrong. Do not paste and deploy them without validation."},{"id":"prompt-injection","term":"Prompt injection","definition":"Malicious instructions hidden in untrusted text to redirect an AI assistant.","example":"A compromised log entry tries to make an AI ignore operator rules.","category":"Automation, architecture, and expert networking","level":"advanced"},{"id":"human-approval-gate","term":"Human approval gate","definition":"A safety check requiring a person to authorize a consequential automated action.","example":"An assistant can suggest a routing change but must get approval before deployment.","category":"Automation, architecture, and expert networking","level":"advanced"}];
